261	        public void ApplyQueryAttributes(IDictionary<string, object> query)
262	        {
263	            if (query.TryGetValue(QueryKeys.SavedCourse, out var saved) && saved is Course savedCourse)
264	            {
265	                ShowSavedCourse(savedCourse);
266	                query.Remove(QueryKeys.SavedCourse);
267	            }
268	
269	            if (query.TryGetValue(QueryKeys.DeletedCourse, out var deleted) && deleted is Course deletedCourse)
270	            {
271	                _ = ShowDeletedCourseAsync(deletedCourse);
272	                query.Remove(QueryKeys.DeletedCourse);
273	            }
274	        }
