276	        private async Task LoadCoursesAsync(bool forceReload)
277	        {
278	            if (_hasLoaded && !forceReload)
279	            {
280	                IsBusy = false;
281	                return;
282	            }
283	
284	            IsBusy = true;
285	            ErrorMessage = string.Empty;
286	
287	            try
288	            {
289	                var courses = await _courseRepository.GetCoursesAsync();
290	
291	                Courses.Clear();
292	                foreach (var course in courses)
293	                    Courses.Add(course);
294	
295	                var profile = await _gpaProfileRepository.GetProfileAsync();
296	                _startingGpa = profile.StartingGpa;
297	                _startingCredits = profile.StartingCredits;
298	                StartingGpaInput = _startingCredits > 0 ? _startingGpa.ToString("0.##") : string.Empty;
299	                StartingCreditsInput = _startingCredits > 0 ? _startingCredits.ToString("0.##") : string.Empty;
300	
301	                RecalculateGpa();
302	
303	                _hasLoaded = true;
304	            }
305	            catch (Exception)
306	            {
307	                ErrorMessage = "Couldn't load your courses. Check that the API is running and try again.";
308	            }
309	            finally
310	            {
311	                IsBusy = false;
312	            }
313	        }
