315	        private void ShowSavedCourse(Course course)
316	        {
317	            var index = IndexOf(course.ID);
318	            if (index >= 0)
319	                Courses[index] = course;
320	            else
321	                Courses.Add(course);
322	
323	            ErrorMessage = string.Empty;
324	            RecalculateGpa();
325	        }
326	
327	        private async Task ShowDeletedCourseAsync(Course course)
328	        {
329	            var index = IndexOf(course.ID);
330	            if (index >= 0)
331	                Courses.RemoveAt(index);
332	
333	            RecalculateGpa();
334	
335	            await _navigation.ShowAlertAsync("Removed", $"{course.CourseCode} was removed.");
336	        }
337	
338	        public async Task RemoveCourseAsync(Course? course)
339	        {
340	            if (course is null)
341	                return;
342	
343	            IsBusy = true;
344	            ErrorMessage = string.Empty;
345	
346	            try
347	            {
348	                await _authService.RunWriteAsync(async () =>
349	                {
350	                    await _courseRepository.DeleteCourseAsync(course.ID);
351	                    return true;
352	                });
353	            }
354	            catch (Exception exception) when (exception is ApiRequestException or LoginCancelledException)
355	            {
356	                ErrorMessage = exception.Message;
357	                IsBusy = false;
358	                return;
359	            }
360	
361	            IsBusy = false;
362	            await ShowDeletedCourseAsync(course);
363	        }
364	
365	        private async Task SaveStartingGpaAsync()
366	        {
367	            var gpaText = StartingGpaInput?.Trim();
368	            var creditsText = StartingCreditsInput?.Trim();
369	
370	            if (string.IsNullOrEmpty(gpaText) && string.IsNullOrEmpty(creditsText))
371	            {
372	                _startingGpa = 0;
373	                _startingCredits = 0;
374	                await _gpaProfileRepository.SaveProfileAsync(new GpaProfile { StartingGpa = 0, StartingCredits = 0 });
375	                StartingGpaValidationMessage = string.Empty;
376	                RecalculateGpa();
377	                IsEditingStartingGpa = false;
378	                return;
379	            }
380	
381	            if (!double.TryParse(gpaText, out var gpa) || gpa < 0 || gpa > 4.0)
382	            {
383	                StartingGpaValidationMessage = "GPA needs to be a number between 0.0 and 4.0";
384	                return;
385	            }
386	
387	            if (!double.TryParse(creditsText, out var credits) || credits <= 0)
388	            {
389	                StartingGpaValidationMessage = "Credits needs to be a number greater than 0";
390	                return;
391	            }
392	
393	            _startingGpa = gpa;
394	            _startingCredits = credits;
395	            await _gpaProfileRepository.SaveProfileAsync(new GpaProfile { StartingGpa = gpa, StartingCredits = credits });
396	
397	            StartingGpaValidationMessage = string.Empty;
398	            RecalculateGpa();
399	            IsEditingStartingGpa = false;
400	        }
401	
402	        private int IndexOf(int courseId)
403	        {
404	            for (var courseIndex = 0; courseIndex < Courses.Count; courseIndex++)
405	            {
406	                if (Courses[courseIndex].ID == courseId)
407	                    return courseIndex;
408	            }
409	
410	            return -1;
411	        }
412	
413	        private void ApplyFilter()
414	        {
415	            FilteredCourses.Clear();
416	
417	            var query = SearchQuery?.Trim().ToLowerInvariant() ?? string.Empty;
418	
419	            foreach (var course in Courses)
420	            {
421	                if (string.IsNullOrEmpty(query) ||
422	                    course.Name.ToLowerInvariant().Contains(query) ||
423	                    course.CourseCode.ToLowerInvariant().Contains(query) ||
424	                    course.Instructor.ToLowerInvariant().Contains(query))
425	                {
426	                    FilteredCourses.Add(course);
427	                }
428	            }
429	        }
430	
431	        private void BuildSimulationItems()
432	        {
433	            SimulatedAssignments.Clear();
434	
435	            foreach (var course in Courses)
436	            {
437	                var ungradedAssignments = course.Assignments
438	                    .Where(assignment => !assignment.IsCompleted || !assignment.PointsEarned.HasValue);
439	
440	                foreach (var assignment in ungradedAssignments)
441	                {
442	                    SimulatedAssignments.Add(new SimulatedAssignmentItem
443	                    {
444	                        AssignmentId = assignment.ID,
445	                        CourseId = course.ID,
446	                        CourseCode = course.CourseCode,
447	                        Title = assignment.Title,
448	                        PointsPossible = assignment.PointsPossible,
449	                        ExpectedPoints = Math.Round(assignment.PointsPossible * 0.9),
450	                        OnScoreChanged = RecalculateSimulatedGpa
451	                    });
452	                }
453	            }
454	
455	            RecalculateSimulatedGpa();
456	        }
457	
458	        private void RecalculateSimulatedGpa()
459	        {
460	            var simulatedCourses = new List<Course>();
461	
462	            foreach (var course in Courses)
463	            {
464	                var gradedAssignments = course.Assignments
465	                    .Where(assignment => assignment.IsCompleted && assignment.PointsEarned.HasValue && assignment.PointsPossible > 0)
466	                    .ToList();
467	
468	                var pointsEarned = gradedAssignments.Sum(assignment => assignment.PointsEarned!.Value);
469	                var pointsPossible = gradedAssignments.Sum(assignment => assignment.PointsPossible);
470	
471	                foreach (var simulatedAssignment in SimulatedAssignments.Where(item => item.CourseId == course.ID))
472	                {
473	                    pointsEarned += simulatedAssignment.ExpectedPoints;
474	                    pointsPossible += simulatedAssignment.PointsPossible;
475	                }
476	
477	                if (pointsPossible > 0)
478	                {
479	                    var percent = (pointsEarned / pointsPossible) * 100.0;
480	                    var letterGrade = _gpaCalculator.GetLetterGradeFromPercent(percent);
481	
482	                    simulatedCourses.Add(new Course
483	                    {
484	                        ID = course.ID,
485	                        Name = course.Name,
486	                        Credits = course.Credits,
487	                        CurrentGrade = letterGrade,
488	                        GradePoints = _gpaCalculator.GetGradePoints(letterGrade)
489	                    });
490	                }
491	                else
492	                {
493	                    simulatedCourses.Add(course);
494	                }
495	            }
496	
497	            ProjectedGpa = _startingCredits > 0
498	                ? _gpaCalculator.CalculateGpa(simulatedCourses, _startingGpa, _startingCredits)
499	                : _gpaCalculator.CalculateGpa(simulatedCourses);
500	
501	            ProjectedStatus = _gpaCalculator.GetStatus(ProjectedGpa, PtkGoodStandingGpa, PtkInitiationGpa);
502	        }
503	
504	        private void RecalculateGpa()
505	        {
506	            ApplyFilter();
507	
508	            CurrentGpa = _startingCredits > 0
509	                ? _gpaCalculator.CalculateGpa(Courses, _startingGpa, _startingCredits)
510	                : _gpaCalculator.CalculateGpa(Courses);
511	
512	            Status = _gpaCalculator.GetStatus(CurrentGpa, PtkGoodStandingGpa, PtkInitiationGpa);
513	
514	            _themeService.ApplyGpaStatusTheme(Status);
515	
516	            if (IsSimulatorOpen)
517	                RecalculateSimulatedGpa();
518	        }
519	
520	        private void OnCourseSelected(Course? course)
521	        {
522	            if (course is null)
523	                return;
524	
525	            _ = _navigation.GoToAsync(
526	                Routes.CourseDetail,
527	                new Dictionary<string, object> { { QueryKeys.Course, course } });
528	        }
529	    }
530	}
